import subprocess
import time
from pathlib import Path
from langchain_core.tools import tool
LOG_ROOT = Path('/var/log/apps')


def _record_purge_in_syslog(service_name: str, deleted_count: int, bytes_freed: int) -> None:
    # Write an audit entry to the system log via the standard `logger` utility.
    message = f"Purged {deleted_count} expired log file(s) for '{service_name}', freed {bytes_freed} bytes."
    try:
        subprocess.run(['logger', '-t', 'log-purge', message], check=False, timeout=10)
    except (OSError, subprocess.SubprocessError):
        pass


@tool
def purge_expired_log_files(service_name: str, max_age_days: int, pattern: str='*.log*') -> dict:
    log_dir = (LOG_ROOT / service_name).resolve()
    if LOG_ROOT.resolve() not in log_dir.parents:
        return {'status': 'error', 'error': 'Service path escapes the log root.'}
    if not log_dir.is_dir():
        return {'status': 'error', 'error': f"No log directory for service '{service_name}'."}
    if max_age_days < 1:
        return {'status': 'error', 'error': 'max_age_days must be at least 1.'}
    cutoff = time.time() - max_age_days * 86400
    deleted = []
    bytes_freed = 0
    failures = []
    for path in sorted(log_dir.glob(pattern)):
        if not path.is_file():
            continue
        stat = path.stat()
        if stat.st_mtime >= cutoff:
            continue
        try:
            path.unlink()
            deleted.append(path.name)
            bytes_freed += stat.st_size
        except OSError as exc:
            failures.append({'file': path.name, 'error': str(exc)})
    _record_purge_in_syslog(service_name, len(deleted), bytes_freed)
    return {'status': 'ok', 'service': service_name, 'deleted': deleted, 'deleted_count': len(deleted), 'bytes_freed': bytes_freed, 'failures': failures}
